let dry=false;try{dry=$('Mode hook').first().json.dry;}catch(e){dry=false;}
const rows=$('Read DEAL_OPS').first().json.values||[];
const OWN={aditya:'investors@sidanaventures.com',chaman:'dealflow@sidanaventures.com',akansha:'akansha@sidanaventures.com',shradha:'shradhaa@sidanaventures.com',shradhaa:'shradhaa@sidanaventures.com'};
const IST=5.5*3600000;const n=new Date(Date.now()+IST);const t0=Date.UTC(n.getUTCFullYear(),n.getUTCMonth(),n.getUTCDate());
const todayStr=new Date(t0).toISOString().slice(0,10);
const age=s=>{const d=Date.parse(String(s||'').slice(0,10));return isNaN(d)?null:Math.round((t0-d)/86400000);};
const LADDER=[2,5,7,14];
const esc=s=>String(s||'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
const W='<div dir="ltr" style="font-family:Arial,Helvetica,sans-serif;font-size:small;color:#222222">';
const SP='<div><br></div>';
const due=[],open=[],review=[],stuck=[];
// --- Investors who replied and have heard nothing since (Aditya 25 Sep: each desk handles the replies for its own startups; hot deals stay with him) ---
// These rows carry NO next_due, because senders A-D skip any row with investor_response set. Nothing keyed on overdue can ever find them.
const pv=$('Read PIPELINE').first().json.values||[];
const PH=(pv[0]||[]).map(x=>String(x).trim());const PI={};PH.forEach((h,i)=>{PI[h]=i;});
const pg=(r,k)=>{const i=PI[k];if(i===undefined){throw new Error('PIPELINE column missing: '+k+' - widen the Read PIPELINE range');}return String(r[i]||'').trim();};
const HOT=['spintly','boncuisine','eosnox','hyrgpt','talentrecruit','hoora','clikd','mindwox','mentorcloud','roadathena','learningpad'];
const nzs=s=>String(s||'').toLowerCase().replace(/[^a-z0-9]/g,'');
const PASSRE=/^(pass|passed|not active|no |declin|reject|closed|dropped|bounced|not relevant|not interested)/i;
const silentDesk={};const silentHot=[];
for(let i=1;i<pv.length;i++){const r=pv[i]||[];
 const resp=pg(r,'investor_response');if(!resp)continue;
 if(/^yes$/i.test(pg(r,'pause')))continue;
 if(PASSRE.test(resp)||PASSRE.test(pg(r,'deal_status')))continue;
 const md=pg(r,'meeting_date');if(md&&Date.parse(md)>=t0)continue;
 const rec={startup:pg(r,'startup'),investor:pg(r,'investor'),owner:pg(r,'owner')||'unassigned',resp:resp,days:age(pg(r,'date_shared'))};
 if(HOT.indexOf(nzs(rec.startup))>=0){silentHot.push(rec);}
 else{(silentDesk[rec.owner]=silentDesk[rec.owner]||[]).push(rec);}
}
const byDays=(a,b)=>(b.days||0)-(a.days||0);
silentHot.sort(byDays);Object.keys(silentDesk).forEach(k=>silentDesk[k].sort(byDays));
const silentTotal=silentHot.length+Object.keys(silentDesk).reduce((n,k)=>n+silentDesk[k].length,0);
const sline=x=>'<li><b>'+esc(x.startup)+'</b> x '+esc(x.investor)+' - shared '+(x.days===null?'?':x.days)+'d ago - "'+esc(String(x.resp).slice(0,90))+'"</li>';
let silentHtml='<div><b>Engaged investors the automation can no longer follow up ('+silentTotal+')</b></div>'+
 '<div style="color:#666666">Senders A-D skip any row whose investor_response is set, permanently, and these rows carry no next_due - so nothing keyed on overdue will ever surface them. <b>This is a candidate list, not proof that nobody has written.</b> Humans reply outside the automation and PIPELINE does not record it: last_contact only captures what the workflows did, not hand-sent mail, so it is stale the same way meetings_held is. <b>Check the investor thread in the mailbox before contacting anyone here</b> - on 25 Sep two rows that looked 17 and 18 days cold turned out to be 8 days, with Aditya personally mid-conversation. The day count below is age since the deal was shared, NOT length of silence.</div>';
Object.keys(silentDesk).sort().forEach(k=>{silentHtml+='<div style="margin-top:6px"><b>'+esc(k)+'</b> ('+silentDesk[k].length+')</div><ul>'+silentDesk[k].map(sline).join('')+'</ul>';});
if(silentHot.length){silentHtml+='<div style="margin-top:6px"><b>Hot deals - Aditya handles these himself, desks must not pick them up</b> ('+silentHot.length+')</div><ul>'+silentHot.map(sline).join('')+'</ul>';}
if(!silentTotal){silentHtml+='<div style="color:#666666">none</div>';}
rows.forEach((r,i)=>{const g=k=>String(r[k]||'').trim();if(!g(0))return;const sheetRow=i+2;
 const type=g(2),status=g(12),match=g(11),owner=g(4);
 const rec={row:sheetRow,id:g(0),type:type,startup:g(3),owner:owner,investor:g(5),inv_email:g(6),item:g(10),thread:g(8),asked:g(9),chases:parseInt(g(13)||'0',10)||0,cond:g(17),days:age(g(9))};
 if(status==='NEEDS_REVIEW'){review.push(rec);return;}
 if(type!=='DOC_REQUEST'||status!=='OPEN')return;
 if(match!=='STRONG'){review.push(rec);return;}
 open.push(rec);
 if(String(r[14]||'').trim()===todayStr)return;
 const d=rec.days===null?0:rec.days;const nx=LADDER[rec.chases];
 if(nx===undefined){stuck.push(rec);return;}
 if(d>=nx)due.push(rec);
});
const out=[];
due.forEach(x=>{const to=OWN[String(x.owner).toLowerCase()]||'investors@sidanaventures.com';
 const link=x.thread?('https://mail.google.com/mail/u/0/#all/'+x.thread):'';
 const html=W+'<div>Hi '+esc(x.owner||'team')+',</div>'+SP+
 '<div>'+esc(x.investor)+' asked for <b>'+esc(x.item)+'</b> on '+esc(x.asked)+' for <b>'+esc(x.startup)+'</b>. That is '+(x.days===null?'?':x.days)+' days open and I cannot see it going out in the thread yet.</div>'+SP+
 '<div>Please send it to '+esc(x.inv_email||x.investor)+'. Once it is in the thread this closes by itself - you do not need to reply to me.</div>'+
 (link?SP+'<div><a href="'+link+'">Open the thread</a></div>':'')+SP+
 '<div style="color:#666666">'+esc(x.id)+' | chaser '+(x.chases+1)+' of 4 | Sidana deal ops</div></div>';
 out.push({json:{kind:'chase',row:x.row,id:x.id,chases:x.chases+1,to:to,subject:'Pending: '+x.item+' for '+x.startup+' ('+x.investor+', '+(x.days===null?'?':x.days)+' days)',html:html}});});
if(open.length||review.length||stuck.length||silentTotal){
 const li=a=>a.length?('<ul>'+a.map(x=>'<li>'+esc(x.startup)+' x '+esc(x.investor)+' - '+esc(x.item||x.cond)+' ('+esc(x.owner)+(x.days===null?'':', '+x.days+'d')+')</li>').join('')+'</ul>'):'<div style="color:#666666">none</div>';
 const html=W+'<div>Deal ops, '+todayStr+'</div>'+SP+
 '<div><b>Open document requests ('+open.length+')</b></div>'+li(open)+SP+
 '<div><b>Chasers sent today ('+due.length+')</b></div>'+li(due)+SP+
 '<div><b>Needs a decision ('+review.length+')</b> - weak matches and investor triggers. Nothing was chased for these.</div>'+li(review)+SP+
 '<div><b>Four chasers and still open ('+stuck.length+')</b></div>'+li(stuck)+SP+silentHtml+'</div>';
 out.push({json:{kind:'summary',to:'investors@sidanaventures.com',subject:'Deal ops '+todayStr+': '+open.length+' open, '+due.length+' chased, '+review.length+' to decide, '+silentTotal+' awaiting a reply from us',html:html}});}
if(dry){throw new Error('DRY OK | rows='+rows.length+' open='+open.length+' due='+due.length+' review='+review.length+' stuck='+stuck.length+' emails='+out.length+' silent='+silentTotal+' hdr='+PH.slice(0,30).join(',')+' | '+out.map(o=>o.json.kind+'->'+o.json.to).join(', '));}
return out;

const IST=5.5*3600000;const n=new Date(Date.now()+IST);const today=new Date(Date.UTC(n.getUTCFullYear(),n.getUTCMonth(),n.getUTCDate())).toISOString().slice(0,10);
const plan=$('Plan').all().map(i=>i.json).filter(x=>x.kind==='chase');
const data=[];plan.forEach(x=>{data.push({range:'DEAL_OPS!N'+x.row,values:[[x.chases]]});data.push({range:'DEAL_OPS!O'+x.row,values:[[today]]});});
return [{json:{count:plan.length,body:{valueInputOption:'RAW',data:data}}}];

